-- 精简版配套数据：仅与 2026-09-11 版 T132.sql 配合使用。
-- 执行顺序：USE t132; SOURCE T132.sql; SOURCE database/003_teaching_seed.sql;
-- 管理员：admin / Teaching2026!；公开初始化密码，使用后修改。
-- 教师以 TMP 工号登录，密码为随机摘要，由后续适配的管理员功能重置。
-- 来源：老师的 255 行课表；项目采集文件为模板和示例，不插入正式项目。
-- 不包含本机后来新增的测试任务、项目、登录令牌或本机账号密码。
-- 原始 21 列课表完整保存在 teaching_import_row.raw_data。
-- 已有数据会被拒绝，任何 INSERT 出错均回滚本次全部插入。
-- 初始化时保留2025-2026历史学期和2026-2027学期；此文件不会自动随日期滚动。
-- Counts: {"account": 80, "academic_term": 4, "course": 93, "laboratory": 14, "teaching_import_batch": 1, "teaching_import_row": 255, "teaching_task": 255, "teaching_task_teacher": 269, "schedule_detail": 2208, "experiment_project": 0, "token": 0}
SET NAMES utf8mb4;
SET @simple_seed_old_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION,NO_BACKSLASH_ESCAPES';
DELIMITER $$
DROP PROCEDURE IF EXISTS install_teaching_seed_20260911$$
CREATE PROCEDURE install_teaching_seed_20260911()
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  IF ((SELECT COUNT(*) FROM `account`) + (SELECT COUNT(*) FROM `academic_term`) + (SELECT COUNT(*) FROM `course`) + (SELECT COUNT(*) FROM `laboratory`) + (SELECT COUNT(*) FROM `teaching_import_batch`) + (SELECT COUNT(*) FROM `teaching_import_row`) + (SELECT COUNT(*) FROM `teaching_task`) + (SELECT COUNT(*) FROM `teaching_task_teacher`) + (SELECT COUNT(*) FROM `schedule_detail`) + (SELECT COUNT(*) FROM `experiment_project`) + (SELECT COUNT(*) FROM `token`)) <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Teaching seed requires empty tables; existing data was not changed';
  END IF;


